#!/bin/bash
# Generated by dsh-mac-intel-update. Runs as root via:
#   osascript -e 'do shell script "nohup /bin/bash <this> >> <log> 2>&1 &" with administrator privileges'
#
# 这里做所有需要写 /Applications 的动作：等调用方返回、退出应用、挂载 dmg、
# 替换 bundle、清 quarantine、以原用户身份重启，并把结果写进 last-install.json。
set -u
LOG="@@LOG@@"
exec >>"$LOG" 2>&1
echo "[$(/bin/date '+%Y-%m-%d %H:%M:%S')] install start version=@@EXPECT@@"
APP="@@APP@@"
DMG="@@DMG@@"
EXPECT="@@EXPECT@@"
RESULT="@@RESULT@@"
OWNER_UID=@@UID@@
OWNER_GID=@@GID@@
MNT="$(/usr/bin/mktemp -d /tmp/dsh-mac-intel-install.XXXXXX)"

finish() {
  printf '{"ok":%s,"version":"%s","message":"%s","at":"%s"}\n' "$1" "$EXPECT" "$2" "$(/bin/date -u '+%Y-%m-%dT%H:%M:%SZ')" > "$RESULT"
  /usr/sbin/chown "$OWNER_UID:$OWNER_GID" "$RESULT" 2>/dev/null || true
  /usr/sbin/chown "$OWNER_UID:$OWNER_GID" "$LOG" 2>/dev/null || true
}

cleanup() {
  /usr/bin/hdiutil detach "$MNT" -quiet -force >/dev/null 2>&1 || true
  /bin/rm -rf "$MNT"
}
trap cleanup EXIT

# 给 HTTP 响应和界面留出时间，再退出应用
/bin/sleep 2
echo "quit app"
/usr/bin/pkill -f "$APP/Contents/MacOS" >/dev/null 2>&1 || true
i=0
while [ "$i" -lt 60 ]; do
  /usr/bin/pgrep -f "$APP/Contents/MacOS" >/dev/null 2>&1 || break
  /bin/sleep 0.5
  i=$((i + 1))
done
/usr/bin/pkill -9 -f "$APP/Contents/MacOS" >/dev/null 2>&1 || true

echo "attach $DMG"
if ! /usr/bin/hdiutil attach -nobrowse -quiet -mountpoint "$MNT" "$DMG"; then
  finish false "挂载 dmg 失败"
  exit 1
fi
if [ ! -d "$MNT/DeepSeek Harness.app" ]; then
  finish false "dmg 内未找到 DeepSeek Harness.app"
  exit 1
fi

echo "replace $APP"
/bin/rm -rf "$APP"
if ! /usr/bin/ditto "$MNT/DeepSeek Harness.app" "$APP"; then
  finish false "写入 /Applications 失败"
  exit 1
fi
/usr/bin/xattr -dr com.apple.quarantine "$APP" >/dev/null 2>&1 || true
/usr/bin/hdiutil detach "$MNT" -quiet -force >/dev/null 2>&1 || true

NEW="$(/usr/bin/defaults read "$APP/Contents/Info" CFBundleShortVersionString 2>/dev/null)"
echo "new version: $NEW expected: $EXPECT"
if [ "$NEW" != "$EXPECT" ]; then
  finish false "写入后版本是 $NEW，期望 $EXPECT"
else
  finish true "已更新到 $NEW"
fi

echo "relaunch"
/usr/bin/launchctl asuser "$OWNER_UID" /usr/bin/open -a "$APP" >/dev/null 2>&1 || /usr/bin/open -a "$APP" >/dev/null 2>&1 || true
exit 0
